contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}
    function run(uint256 depositAmt) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (depositAmt)); require(depositAmt <= 1000000000000000000000000000000);
        require(depositAmt > 0);
        require(address(this).balance >= depositAmt);
        c.deposit{value: depositAmt}(); if (__ESBMC_reverted()) return;
        uint256 balBefore = address(c).balance;
        bool reverted;
        c.refund(); bool __rev0 = __ESBMC_reverted(); if (__rev0) { reverted = true; } else { reverted = false; }
        uint256 balAfter = address(c).balance;
        assert(!reverted && balBefore >= depositAmt && balAfter == balBefore - depositAmt);
    }
    receive() external payable {}
}

